        return "NO"

    half = n // 2
    even_sum = sum(range(2, half * 2 + 1, 2))
    odd_sum = sum(range(1, half * 2 + 1, 2))

    if even_sum == odd_sum:
        return "YES", list(range(2, half * 2 + 1, 2)) + list(range(1, half * 2 + 1, 2))

    diff = abs(even_sum - odd_sum)

    if diff % 2 != 0:
        return "NO"

    if even_sum > odd_sum:
        # Try to reduce even_sum by swapping with odd numbers
        for i in range(half):
            if (even_sum - (2 * i + 2) + (2 * i + 1)) == odd_sum:
                return "YES", list(range(2, half * 2 + 1, 2))[:i] + [2 * i + 1] + list(range(2 * i + 2, half * 2 + 1, 2)) + list(range(1, half * 2 + 1, 2))
    else:
        # Try to increase odd_sum by swapping with even numbers
        for i in range(half):
            if (odd_sum + (2 * i + 2) - (2 * i + 1)) == even_sum:
